NativeSignal grp0_blit_bitmap(VM& vm, Thread& thread) {
    const uint32_t parameter = thread.stack.pop();
    const uint32_t mode = thread.stack.pop();
    const uint32_t source = thread.stack.pop();
    const int32_t y = static_cast<int32_t>(thread.stack.pop());
    const int32_t x = static_cast<int32_t>(thread.stack.pop());
    const uint32_t destination = thread.stack.pop();
    if(debug_trace(DebugTrace::GpuFrames) && std::getenv("BGI_TRACE_BITMAP_GEOMETRY")) {
        std::cerr<<"BITMAP_TRANSFER dst="<<destination<<" src="<<source<<" xy="<<x<<','<<y
            <<" mode="<<mode<<" parameter="<<parameter;
        for(const auto id:{destination,source}) {
            const auto it=vm.graphics_surfaces().find(id);
            if(it!=vm.graphics_surfaces().end())std::cerr<<" surface="<<id<<':'<<it->second.format<<':'
                <<it->second.width<<'x'<<it->second.height<<":"<<bool(it->second.pixels.gpu_storage());
        }
        std::cerr<<'\n';
    }
    if (!vm.record_bitmap_blit(
            destination, source, x, y, mode, parameter)) {
        std::ostringstream message;
        message << "Grp0:0x18 invalid bitmap pair dst=0x" << std::hex
                << std::uppercase << destination << " src=0x" << source
                << " mode=0x" << mode << " parameter=0x" << parameter
                << std::dec << " position=" << x << ',' << y;
        for (const auto& [label, slot] :
             {std::pair{"dst", destination}, std::pair{"src", source}}) {
            if (const auto surface = vm.graphics_surfaces().find(slot);
                surface != vm.graphics_surfaces().end()) {
                message << ' ' << label << "_format=" << surface->second.format
                        << ' ' << label << "_size=" << surface->second.width
                        << 'x' << surface->second.height;
            } else {
                message << ' ' << label << "_missing";
                if (const auto error = vm.bitmap_load_errors().find(slot);
                    error != vm.bitmap_load_errors().end()) {
                    message << ' ' << label << "_error=" << error->second;
                }
            }
        }
        throw std::runtime_error(message.str());
    }
    return NativeSignal::Continue;
}
